-- SQL baseline (applied to production 2026-10-03, PostgreSQL 18; compatible with 16).
-- Changes go through a reviewed PR; Phase B moves this into Drizzle migrations.
-- ids are generated by the application (no DB defaults).

CREATE TABLE clinic_features (
  clinic_id  uuid NOT NULL REFERENCES clinics (id),
  id         uuid NOT NULL,
  module     text NOT NULL CHECK (module IN ('patients')),
  enabled    boolean NOT NULL,
  updated_at timestamptz NOT NULL,
  PRIMARY KEY (clinic_id, id),
  UNIQUE (clinic_id, module)
);

ALTER TABLE clinic_features ENABLE ROW LEVEL SECURITY;
ALTER TABLE clinic_features FORCE ROW LEVEL SECURITY;
CREATE POLICY clinic_features_tenant_isolation ON clinic_features
  USING (clinic_id = current_setting('app.clinic_id')::uuid)
  WITH CHECK (clinic_id = current_setting('app.clinic_id')::uuid);
